package com.yeyamo_mobile.api.feed_service.infrastructure.persistence;import java.time.Instant;import java.util.UUID;import jakarta.persistence.*;@Entity@Table(name="feed_user_post_signals",uniqueConstraints=@UniqueConstraint(name="uk_feed_signal_user_post",columnNames={"user_id","post_id"}))public class FeedSignalEntity{@Id private UUID id;@Column(name="user_id",nullable=false,length=120)private String userId;@Column(name="post_id",nullable=false)private UUID postId;@Column(nullable=false)private double weight;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version private long version;public UUID getId(){return id;}public void setId(UUID v){id=v;}public String getUserId(){return userId;}public void setUserId(String v){userId=v;}public UUID getPostId(){return postId;}public void setPostId(UUID v){postId=v;}public double getWeight(){return weight;}public void setWeight(double v){weight=v;}public Instant getUpdatedAt(){return updatedAt;}public void setUpdatedAt(Instant v){updatedAt=v;}}
